import{_ as d,C as r,o,c as n,E as l,a4 as a}from"./chunks/framework.BMj-uaUw.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"先看一个 400 行的页面","slug":"先看一个-400-行的页面","link":"#先看一个-400-行的页面","children":[]},{"level":2,"title":"组件化的收益来自“接口”，不是来自“文件数”","slug":"组件化的收益来自-接口-不是来自-文件数","link":"#组件化的收益来自-接口-不是来自-文件数","children":[]},{"level":2,"title":"本单元的知识地图","slug":"本单元的知识地图","link":"#本单元的知识地图","children":[]},{"level":2,"title":"这次课的 4 学时怎么用","slug":"这次课的-4-学时怎么用","link":"#这次课的-4-学时怎么用","children":[]},{"level":2,"title":"开始之前","slug":"开始之前","link":"#开始之前","children":[]},{"level":2,"title":"这个单元的两个产出","slug":"这个单元的两个产出","link":"#这个单元的两个产出","children":[]},{"level":2,"title":"读完之后","slug":"读完之后","link":"#读完之后","children":[]}],"relativePath":"unit07/index.md","filePath":"unit07/index.md","lastUpdated":1789356894000}'),i={name:"unit07/index.md"};function s(c,t,h,p,g,u){const e=r("UnitMeta");return o(),n("div",null,[l(e,{unit:"单元 7",title:"组件基础与父子通信",module:"模块三 · 组件化开发",hours:"4 学时",week:"第 7 周",goals:["能按职责合理拆分组件，并说清拆分理由","能设计清晰的组件接口：需要什么属性、会发出什么事件","能实现父子组件之间的双向通信"],outcomes:["自研卡片组件","可自定义单元格的表格组件"]}),t[0]||(t[0]=a('<h2 id="先看一个-400-行的页面" tabindex="-1">先看一个 400 行的页面 <a class="header-anchor" href="#先看一个-400-行的页面" aria-label="Permalink to &quot;先看一个 400 行的页面&quot;">​</a></h2><p>活动详情页的第一版是这样的：一个 <code>ActivityDetailView.vue</code>，<strong>400 行</strong>。里面装着：</p><ul><li>顶部活动标题、状态标签、操作按钮（编辑、下架、导出报名名单）</li><li>中部的活动信息表（类型、组织者、报名截止时间、名额、已通过人数）</li><li>报名进度条</li><li>场次与场地列表</li><li>报名记录表格（带搜索、状态筛选、分页）</li><li>底部的审核记录时间线</li></ul><p>这个页面能跑，也能交付。问题出在<strong>第二次改需求</strong>的时候：</p><blockquote><p>需求一：活动列表页也要显示“报名进度条”。 需求二：审核页也要用“报名记录表格”，但那边不显示“导出”按钮。 需求三：场次列表在另一个页面（场次管理）也要用。</p></blockquote><p>三个需求意味着三处改动，而每次改动都要在 400 行里找到对应的那段，还要小心别碰坏旁边的逻辑。 第二次、第三次之后，没人敢动这个文件了。</p><p><strong>这就是组件化要解决的问题。</strong> 这个单元教你两件事：<strong>怎么拆</strong>，以及<strong>拆完之后父子之间怎么说话。</strong></p><h2 id="组件化的收益来自-接口-不是来自-文件数" tabindex="-1">组件化的收益来自“接口”，不是来自“文件数” <a class="header-anchor" href="#组件化的收益来自-接口-不是来自-文件数" aria-label="Permalink to &quot;组件化的收益来自“接口”，不是来自“文件数”&quot;">​</a></h2><p>先把一个常见的误区说清楚：<strong>拆成组件不等于变好。</strong></p><p>如果拆完之后，父组件需要给子组件传八个属性才能让它工作，或者子组件里到处读父组件的数据， 那你只是把一个 400 行的文件变成了五个互相纠缠的文件，<strong>总复杂度反而上升了</strong>。</p><p>真正带来收益的是<strong>清晰的接口</strong>。所谓接口，就是两句话：</p><blockquote><p>这个组件<strong>需要</strong>什么？（属性，props） 这个组件<strong>会告诉外面</strong>什么？（事件，emits）</p></blockquote><p>有了这两句话，组件才是一个“能独立讲清楚的东西”。别人用你的组件时，不需要读它的内部实现， 只需要看它的接口。</p><h2 id="本单元的知识地图" tabindex="-1">本单元的知识地图 <a class="header-anchor" href="#本单元的知识地图" aria-label="Permalink to &quot;本单元的知识地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>小节</th><th>讲什么</th><th>解决什么问题</th></tr></thead><tbody><tr><td><a href="/frontend-engineering-course/unit07/01-sfc.html">7.1 单文件组件与拆分依据</a></td><td>三段结构、<code>scoped</code> 的原理与失效场景、拆分信号与反信号</td><td>该不该拆、按什么拆</td></tr><tr><td><a href="/frontend-engineering-course/unit07/02-props.html">7.2 父子通信：props</a></td><td>声明方式、类型校验、默认值、单向数据流、解构的响应性</td><td>数据怎么从父传到子</td></tr><tr><td><a href="/frontend-engineering-course/unit07/03-emits.html">7.3 父子通信：emits</a></td><td>声明与触发、命名规则、参数校验、排查监听不到</td><td>数据怎么从子传到父</td></tr><tr><td><a href="/frontend-engineering-course/unit07/04-vmodel.html">7.4 组件上的 v-model</a></td><td><code>modelValue</code> 加事件、多个 v-model、自定义修饰符、<code>defineModel</code></td><td>双向绑定怎么做到</td></tr><tr><td><a href="/frontend-engineering-course/unit07/05-case-tree.html">案例 03 · 树状视图与递归组件</a></td><td>递归自引用、展开收起、搜索自动展开祖先、叶子选中</td><td>数据结构本身是树怎么办</td></tr><tr><td><a href="/frontend-engineering-course/unit07/06-case-editable-table.html">案例 09 · 可编辑表格</a></td><td>单元格编辑态、三个提交出口、方向键移动、脏检查、批量操作</td><td>表格里怎么就地编辑</td></tr><tr><td><a href="/frontend-engineering-course/unit07/ai-collaboration.html">AI 协作 · 组件边界的判断</a></td><td>单向数据流、拆分粒度、props 与 emits 的完整声明</td><td>拆不拆由你判断，不由它决定</td></tr><tr><td><a href="/frontend-engineering-course/unit07/practice.html">课后练习</a></td><td>拆分列表页、分页器、可清空搜索框、评论楼中楼</td><td>上手做</td></tr></tbody></table><p>七节的关系是：先学会<strong>拆</strong>（7.1），再学会<strong>传</strong>（7.2、7.3），然后学会<strong>双向传</strong>（7.4）， 最后用两个案例把“数据是树”“操作在表格里”这两个典型场景做一遍。</p><h2 id="这次课的-4-学时怎么用" tabindex="-1">这次课的 4 学时怎么用 <a class="header-anchor" href="#这次课的-4-学时怎么用" aria-label="Permalink to &quot;这次课的 4 学时怎么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>时长</th><th>做什么</th></tr></thead><tbody><tr><td>检查预习</td><td>0.3 学时</td><td>抽问：把一个页面拆成组件，判断依据是什么？<code>props</code> 为什么不能改？</td></tr><tr><td>讲解</td><td>1.4 学时</td><td>重点讲 7.1 的拆分依据与 7.2 的单向数据流；7.3 讲清事件名的书写规则</td></tr><tr><td>现场任务</td><td>1.8 学时</td><td>两人一组，把自己作业里的活动列表页拆成至少三个组件，并画出接口表</td></tr><tr><td>复盘</td><td>0.5 学时</td><td>挑两组对比：拆得多的是不是更好？哪些属性其实不该传？</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">这次课最容易做偏的两件事</p><ol><li><strong>为了拆而拆</strong> —— 把 20 行的模板拆成 4 个组件，父组件传 10 个属性。 判断标准是“这个组件能不能独立讲清楚”，不是“文件数够不够多”。</li><li><strong>改 props</strong> —— 子组件里写 <code>props.list.push(item)</code>，数据看起来变了，但父组件的数据也跟着被改了， 控制台还会给警告。这是本单元必须彻底搞清楚的一条。</li></ol></div><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><p>这一单元需要你先掌握：</p><ul><li><strong>单元 6</strong>：事件处理与 <code>v-model</code>。组件上的 <code>v-model</code> 是它的延伸。</li><li><strong>单元 5</strong>：<code>v-for</code> 与 <code>:key</code>、四态页面。列表类组件会用到。</li></ul><p>另外，这一单元会大量用到<strong>对象与数组的操作</strong>：展开运算符、<code>filter</code>、<code>map</code>、<code>find</code>。 如果不熟，建议先补一下 —— 本单元里“不修改原数组、返回新数组”的写法会反复出现。</p><h2 id="这个单元的两个产出" tabindex="-1">这个单元的两个产出 <a class="header-anchor" href="#这个单元的两个产出" aria-label="Permalink to &quot;这个单元的两个产出&quot;">​</a></h2><p><strong>一、自研卡片组件</strong></p><p>不是用 UI 库的 <code>Card</code>，而是自己写一个：</p><table tabindex="0"><thead><tr><th>要求</th><th>说明</th></tr></thead><tbody><tr><td>可复用</td><td>至少在两个页面里用过</td></tr><tr><td>有接口</td><td>属性不超过四个，事件不超过两个</td></tr><tr><td>有默认值</td><td>不传属性时也能正常显示</td></tr><tr><td>能装内容</td><td>主体区域可以放任意内容（这个能力在<a href="/frontend-engineering-course/unit08/01-slots.html">单元 8 的插槽</a>里正式学）</td></tr></tbody></table><p><strong>二、可自定义单元格的表格组件</strong></p><p>这是本单元的核心产出。要求：</p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>数据通过属性传入</td><td>表格组件自己不持有数据源</td></tr><tr><td>列配置通过属性传入</td><td>列宽、标题、对齐方式由使用方决定</td></tr><tr><td>操作通过事件上抛</td><td>点击某一行、点某个按钮，都通过事件通知父组件</td></tr><tr><td>至少两种单元格形态</td><td>比如文本、状态标签、操作按钮</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">为什么是“表格”</p><p>因为它是最能暴露接口设计问题的场景：<strong>表格组件要足够通用， 就必须把所有“这块怎么显示、点了做什么”的决定权交回给使用方。</strong></p><p>你会在 7.2 和 7.3 里反复回到这个问题。</p></div><h2 id="读完之后" tabindex="-1">读完之后 <a class="header-anchor" href="#读完之后" aria-label="Permalink to &quot;读完之后&quot;">​</a></h2><p>这个单元结束时，你应该能拿着一个组件，用三句话介绍它：</p><ol><li>它<strong>需要</strong>什么属性，每个属性是什么类型、有没有默认值。</li><li>它<strong>会发出</strong>哪些事件，每个事件带什么数据。</li><li>它<strong>不管</strong>什么 —— 也就是哪些决定权在使用方手里。</li></ol><p>能说清这三句，你的组件就具备了被复用和交接的基础。下一单元 <a href="/frontend-engineering-course/unit08/">单元 8：组件进阶与逻辑复用</a>会在此基础上讲插槽、依赖注入与组合式函数。</p>',35))])}const f=d(i,[["render",s]]);export{m as __pageData,f as default};
